SELECT COUNT(1) AS totalRepairCount, SUM(CASE WHEN status = #{pending} THEN 1 ELSE 0 END) AS pendingDispatchCount, SUM(CASE WHEN status = #{repairing} THEN 1 ELSE 0 END) AS repairingCount, SUM(CASE WHEN status = #{completed} THEN 1 ELSE 0 END) AS repairedCount, SUM(CASE WHEN check_status = #{checkStatus} THEN 1 ELSE 0 END) AS acceptedCount FROM repair_mgmt WHERE deleted=0
AND dorm_num like CONCAT('%', #{dormBuilding}, '%')
AND apply_time between #{startTime} AND #{endTime}
